<?php
$id=(int)($_GET['id']??0);$u=sr_current();
$j=sr_one('SELECT j.*,d.job_type,d.work_mode,d.level,d.deadline,d.benefits,r.website FROM jobs j LEFT JOIN job_details d ON d.job_id=j.id LEFT JOIN recruiter_profiles r ON r.user_id=j.recruiter_id WHERE j.id=? AND j.status=\'approved\' AND (d.deadline IS NULL OR d.deadline>=CURDATE())',[$id]);
if (!$j):?><div class="panel empty-state"><h2>Công việc không còn khả dụng</h2><p>Tin tuyển dụng có thể đã hết hạn hoặc chưa được phê duyệt.</p><a class="button primary" href="<?=sr_url('home')?>">Quay về danh sách việc làm</a></div><?php else:
$applied=($u && $u['role']==='candidate')?sr_one('SELECT id,status,score FROM applications WHERE candidate_id=? AND job_id=?',[$u['id'],$id]):null;
$saved=($u && $u['role']==='candidate')?sr_one('SELECT job_id FROM saved_jobs WHERE user_id=? AND job_id=?',[$u['id'],$id]):null;
?><div class="breadcrumbs"><a href="<?=sr_url('home')?>">Việc làm</a><span>/</span><span>Chi tiết tuyển dụng</span></div><div class="job-detail-top panel"><div class="job-detail-info"><div class="company-logo large"><?=h(sr_initials($j['company']))?></div><div><div class="overline">CƠ HỘI NGHỀ NGHIỆP</div><h1><?=h($j['title'])?></h1><p><?=h($j['company'])?> · <?=h($j['location']?:'Toàn quốc')?></p><div class="tag-row"><span class="chip"><?=h(sr_status($j['job_type']??'full_time'))?></span><span class="chip"><?=h(sr_status($j['work_mode']??'onsite'))?></span><span class="chip"><?=h(sr_status($j['level']??'junior'))?></span></div></div></div><div class="job-detail-actions"><?php if(!$u):?><a class="button primary" href="<?=sr_url('login')?>">Đăng nhập để ứng tuyển</a><?php elseif($u['role']==='candidate'):?><?php if($applied):?><span class="badge success">Đã ứng tuyển · <?=h(sr_status($applied['status']))?></span><?php else:?><form method="post" data-confirm="Gửi CV của bạn tới nhà tuyển dụng cho vị trí này?"><?=sr_token()?><input type="hidden" name="action" value="apply"><input type="hidden" name="back" value="job"><input type="hidden" name="back_id" value="<?=$id?>"><input type="hidden" name="job_id" value="<?=$id?>"><button class="button primary">Ứng tuyển ngay</button></form><?php endif;?><form method="post"><?=sr_token()?><input type="hidden" name="action" value="save_job"><input type="hidden" name="job_id" value="<?=$id?>"><button class="button secondary"><?=$saved?'Bỏ lưu':'Lưu công việc'?></button></form><?php endif;?><button class="button secondary share-job" type="button" data-share-job aria-label="Sao chép liên kết công việc">↗ Chia sẻ</button></div></div>
<div class="detail-layout"><article class="panel content-panel"><h2>Thông tin công việc</h2><div class="description"><?=nl2br(h($j['description']))?></div><h2>Kỹ năng cần có</h2><div class="skills large-skills"><?php foreach(sr_skills($j['skills']) as $s):?><span><?=h($s)?></span><?php endforeach;?></div><?php if(trim((string)$j['benefits'])):?><h2>Quyền lợi</h2><div class="description"><?=nl2br(h($j['benefits']))?></div><?php endif;?></article><aside class="panel detail-aside"><h3>Tổng quan vị trí</h3><div class="fact"><small>Mức lương</small><strong><?=h($j['salary']?:'Thỏa thuận')?></strong></div><div class="fact"><small>Địa điểm</small><strong><?=h($j['location']?:'Toàn quốc')?></strong></div><div class="fact"><small>Hình thức</small><strong><?=h(sr_status($j['job_type']??'full_time'))?></strong></div><div class="fact"><small>Làm việc</small><strong><?=h(sr_status($j['work_mode']??'onsite'))?></strong></div><div class="fact"><small>Hạn nộp hồ sơ</small><strong><?=h(sr_date($j['deadline']??null))?></strong></div><div class="fact"><small>Đăng ngày</small><strong><?=h(sr_date($j['created_at']))?></strong></div><?php if(sr_validate_url((string)($j['website']??'')) && $j['website']):?><a class="text-link" href="<?=h($j['website'])?>" target="_blank" rel="noopener noreferrer">Website doanh nghiệp ↗</a><?php endif;?></aside></div><?php endif;?>
